from collections import deque

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # BFS with shortest path tracking
    dist = [-1] * n
    dist[s] = 0
    queue = deque([s])

    while queue:
        u = queue.popleft()
        for v, w in adj[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + w
                queue.append(v)
            else:
                # If a shorter path is found, update
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    queue.append(v)

    return dist[t]
