def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # Bellman-Ford algorithm to find shortest path from s to t
    dist = [float('inf')] * n
    dist[s] = 0

    for i in range(n - 1):
        updated = False
        for u in range(n):
            if dist[u] == float('inf'):
