        left, right = min(nums), max(nums)
        while left < right:
            mid = (left + right) // 2
            cnt = sum(1 for num in nums if num <= mid)
            if cnt < k:
                left = mid + 1
            else:
                right = mid
        return left
    return kth_smallest(nums, k)
