def solve(nums, k):
    def count_less_equal(x):
        cnt = 0
        for num in nums:
            if num <= x:
                cnt += 1
            if cnt >= k:
                return True
        return cnt >= k

    low = min(nums)
    high = max(nums)
    while low < high:
        mid = (low + high) // 2
        if count_less_equal(mid):
            high = mid
        else:
            low = mid + 1
    return low
```

