def solve(n, edges, s, t):
    if s == t:
        return 0

    from collections import deque

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Bellman-Ford algorithm to find shortest path from s to t
    # Since n <= 100, Bellman-Ford is acceptable
    dist = [float('inf')] * n
    dist[s] = 0

    # Relax edges up to n-1 times
    for _ in range(n - 1):
        for u in range(n):
            if dist[u] == float('inf'):
                continue
            for v, w in adj[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w

    if dist[t] == float('inf'):
        return -1
    else:
        return dist[t]
