# Implementation of a graph and a custom shortest path algorithm (not Dijkstra's)
class Graph:
    def __init__(self):
        self.adj = {}  # adjacency list

    def add_edge(self, u, v, weight):
        if u not in self.adj:
            self.adj[u] = []
        self.adj[u].append((v, weight))

def find_shortest_path(graph, start, end):
    # Initialize distance dictionary
    distances = {node: float('inf') for node in graph.adj}
    distances[start] = 0

    # Priority queue for nodes to visit
    from heapq import heappush, heappop
    heap = [(0, start)]

    while heap:
        current_dist, u = heappop(heap)

        # If we've reached the end node, return the distance
        if u == end:
            return current_dist

        # Skip if we've already found a shorter path to u
        if current_dist > distances[u]:
            continue

        # Explore neighbors
        if u in graph.adj:
            for v, weight in graph.adj[u]:
                if distances[v] > distances[u] + weight:
                    distances[v] = distances[u] + weight
                    heappush(heap, (distances[v], v))

    # If end node is unreachable
    return -1

