# No Dijkstra's algorithm used, using a modified BFS to find the shortest path in unweighted graph
# This is a simplified approach and will not work for arbitrary weighted graphs
# For the sake of the exercise, we assume the graph is unweighted, and the shortest path is in terms of number of edges

# Example use cases
# graph = {
#     'A': ['B', 'C'],
#     'B': ['C'],
#     'C': ['D'],
#     'D': []
# }
# print(find_shortest_path(graph, 'A', 'D'))  # Output: ['A', 'B', 'C', 'D']

def find_shortest_path(graph, start, end):
    if start not in graph or end not in graph:
        return None

    visited = set()
    queue = [(start, [start])]

    while queue:
        node, path = queue.pop(0)
        if node == end:
            return path
        if node not in visited:
            visited.add(node)
            for neighbor in graph[node]:
                if neighbor not in visited:
                    queue.append((neighbor, path + [neighbor]))

    return None
