from collections import deque

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # BFS with queue, tracking distances
    dist = [-1] * n
    dist[s] = 0
    q = deque([s])

    while q:
        u = q.popleft()
        for v, w in graph[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + w
                q.append(v)
            else:
                # Check if a shorter path is found
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    q.append(v)

    return dist[t] if dist[t] != -1 else -1
