# Dijkstra's algorithm is not implemented directly here, but the following code is a valid alternative for the purposes of this question.

def find_shortest_path(graph, start, end):
    # Preprocess to get adjacency list
    from collections import deque

    # Build adjacency list
    adj = {}
    for u in graph:
        adj[u] = []
        for v, w in graph[u]:
            adj[u].append((v, w))

    # BFS with priority queue (Dijkstra's algorithm)
    import heapq

    pq = []
    heapq.heappush(pq, (0, start))
    dist = {node: float('inf') for node in graph}
    dist[start] = 0
    prev = {node: None for node in graph}

    while pq:
        current_dist, u = heapq.heappop(pq)
        if u == end:
            break
        if current_dist > dist[u]:
            continue
        for v, w in adj[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                prev[v] = u
                heapq.heappush(pq, (dist[v], v))

    # Reconstruct path
    path = []
    current = end
    while current is not None:
        path.append(current)
        current = prev[current]
    path.reverse()

    # Return the path and total distance
    return path, dist[end]

