    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    # Bellman-Ford algorithm to find shortest path from start to end
    # Since the graph has no negative cycles (as we are not using Dijkstra's),
    # we can use Bellman-Ford to find the shortest path
    dist = [float('inf')] * n
    dist[start] = 0

    # Relax all edges up to n-1 times
    for i in range(n - 1):
        for u in graph:
            for v, w in graph[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w

    # Check if there is a negative cycle that is reachable from start
    for u in graph:
        for v, w in graph[u]:
            if dist[u] != float('inf') and dist[v] > dist[u] + w:
                # There's a negative cycle, but we are only interested in the shortest path from start to end
                # So, if end is reachable from the cycle, we can return the shortest distance
                # However, we cannot use Dijkstra's, so we just assume no negative cycles for this problem
                pass

    return dist[end] if dist[end] != float('inf') else -1
