# No explicit BFS or DFS is used here. The code implements a manual search for a path in a grid.
# This is a simple depth-first search (DFS) for demonstration purposes.

def find_path(grid, start, end, visited=None, path=None):
    if visited is None:
        visited = set()
    if path is None:
        path = []

    x, y = start
    if (x, y) == end:
        return path + [start]

    visited.add((x, y))
    path.append((x, y))

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    for dx, dy in directions:
        nx, ny = x + dx, y + dy
        if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and (nx, ny) not in visited:
            if grid[nx][ny] == ' ':
                result = find_path(grid, (nx, ny), end, visited, path)
                if result is not None:
                    return result

    path.pop()
    return None

# Example usage
def main():
    grid = [
        "##########",
        "#  #   # #",
        "# #  # # #",
        "#   # #  #",
        "# # #   # #",
        "# #   # # #",
        "# # # # # #",
        "#   #   # #",
        "# # # # # #",
        "##########"
    ]
    start = (1, 1)
    end = (8, 3)

    path = find_path(grid, start, end)
    if path:
        print("Path found:")
        for x, y in path:
            print(f"({x}, {y})")
    else:
        print("No path found.")

if __name__ == "__main__":
    main()
