def solve(grid, start, goal):
    # Check if start or goal is a wall or out of bounds
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0]) and grid[start[0]][start[1]] == '.'):
        return []
    if not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0]) and grid[goal[0]][goal[1]] == '.'):
        return []

    # If start is the same as goal
    if start == goal:
        return [start]

    # Directions: up, right, down, left
    directions = [(-1, 0), (0, 1), (1, 0), (0, -1)]

    # Use a stack for DFS
    stack = [(start, [start])]
    visited = set()
    visited.add(start)

    while stack:
        (current_row, current_col), path = stack.pop()

        for dr, dc in directions:
            new_row, new_col = current_row + dr, current_col + dc

            # Check if new position is within bounds and is a free cell
            if 0 <= new_row < len(grid) and 0 <= new_col < len(grid[0]) and grid[new_row][new_col] == '.':
                if (new_row, new_col) == goal:
                    return path + [(new_row, new_col)]
                if (new_row, new_col) not in visited:
                    visited.add((new_row, new_col))
                    stack.append(((new_row, new_col), path + [(new_row, new_col)]))

    # No path found
    return []
