import heapq

def solve(nums, k):
    # Use a max-heap of size k to keep track of the k smallest elements
    # We use negative numbers to simulate a max-heap with heapq (which is a min-heap)
    heap = []
    for num in nums:
        if len(heap) < k:
            heapq.heappush(heap, -num)
        else:
            if num < -heap[0]:
                heapq.heappop(heap)
                heapq.heappush(heap, -num)
    # The root of the heap is the k-th smallest element
    return -heap[0]
```

