from collections import deque

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Bellman-Ford algorithm to find shortest path from s to t
    dist = [float('inf')] * n
    dist[s] = 0

    # Relax edges up to n-1 times
    for i in range(n - 1):
        for u in range(n):
            if dist[u] != float('inf'):
                for v, w in adj[u]:
                    if dist[v] > dist[u] + w:
                        dist[v] = dist[u] + w

    # Check for negative weight cycles (if any)
    for u in range(n):
        if dist[u] != float('inf'):
            for v, w in adj[u]:
                if dist[v] > dist[u] + w:
                    # If there is a negative cycle, t might be reachable through it
                    # So we need to check if t can be reached from s through any path
                    # To do this, we can use BFS to check reachability
                    visited = [False] * n
                    queue = deque()
                    queue.append(s)
                    visited[s] = True
                    while queue:
                        node = queue.popleft()
                        if node == t:
                            return -1  # t is reachable, but negative cycle exists
                        for v, _ in adj[node]:
                            if not visited[v]:
                                visited[v] = True
                                queue.append(v)
                    # If not reachable, return -1
                    return -1

    return dist[t] if dist[t] != float('inf') else -1
