        # Try all four directions
        if dfs(r - 1, c, path_so_far):
            return True
        if dfs(r + 1, c, path_so_far):
            return True
        if dfs(r, c - 1, path_so_far):
            return True
        if dfs(r, c + 1, path_so_far):
            return True
        # Backtrack
        path_so_far.pop()
        return False

    if dfs(start_row, start_col, path):
        return path
    return []
